{
  "name": "FEI4命令序列控制器",
  "name_en": "FE-I4 Command Sequencer Controller",
  "manufacturer": "",
  "description": "这是一种用于FEI4前端像素读出电子学的FPGA命令序列模块，可存储并输出数字命令序列，并支持重复输出、起始/停止序列长度、输出使能、外部触发和时钟门控等设置。它常用于粒子探测器前端芯片的读出、联调与实验室测试。",
  "description_en": "This is an FPGA-based command sequencer module for FE-I4 front-end pixel readout electronics. It stores and outputs digital command sequences and supports settings such as repetition, start/stop sequence length, output enable, external triggering, and clock gating. It is typically used for readout, integration, and laboratory testing of particle-detector front-end chips.",
  "tag_hints": [
    "FE-I4",
    "FPGA command sequencing",
    "pixel detector electronics",
    "detector readout",
    "external trigger",
    "digital pattern generation"
  ],
  "actions": [
    {
      "action_name": "auto-reset",
      "description": "重置命令序列控制器。",
      "description_en": "Reset the command sequencer controller."
    },
    {
      "action_name": "auto-start",
      "description": "启动命令序列输出。",
      "description_en": "Start command sequence output."
    },
    {
      "action_name": "auto-is_done",
      "description": "检查命令序列是否执行完成。",
      "description_en": "Check whether command sequence execution is complete."
    },
    {
      "action_name": "auto-set_ext_trigger",
      "description": "设置外部触发模式。",
      "description_en": "Set the external trigger mode."
    },
    {
      "action_name": "auto-set_output_mode",
      "description": "设置输出模式。",
      "description_en": "Set the output mode."
    },
    {
      "action_name": "auto-set_clock_gate",
      "description": "设置时钟门控状态。",
      "description_en": "Set the clock gate state."
    },
    {
      "action_name": "auto-set_cmd_pulse",
      "description": "设置命令脉冲参数。",
      "description_en": "Set the command pulse parameter."
    },
    {
      "action_name": "auto-set_size",
      "description": "设置序列数据长度。",
      "description_en": "Set the sequence data length."
    },
    {
      "action_name": "auto-set_repeat",
      "description": "设置重复次数。",
      "description_en": "Set the repeat count."
    },
    {
      "action_name": "auto-set_start_seq_length",
      "description": "设置起始序列长度。",
      "description_en": "Set the start sequence length."
    },
    {
      "action_name": "auto-set_stop_seq_length",
      "description": "设置停止序列长度。",
      "description_en": "Set the stop sequence length."
    },
    {
      "action_name": "auto-set_output_enable",
      "description": "设置输出使能状态。",
      "description_en": "Set the output enable state."
    },
    {
      "action_name": "auto-set_data",
      "description": "设置命令序列数据。",
      "description_en": "Set the command sequence data."
    }
  ]
}

